using UnityEngine;
using Unity.Cinemachine;
using Vector3 = UnityEngine.Vector3;
using System;

public class RoundCameraPos : CinemachineExtension
{
    public float PixelsPerUnit = 32f;

    protected override void PostPipelineStageCallback(
        CinemachineVirtualCameraBase vcam,
        CinemachineCore.Stage stage,
        ref CameraState state,
        float deltaTime)
    {
        if (stage == CinemachineCore.Stage.Body)
        {
            Vector3 finalPos = state.GetFinalPosition();

            Vector3 newPos = new Vector3(
                Round(finalPos.x),
                Round(finalPos.y),
                finalPos.z
            );

            state.PositionCorrection += newPos - finalPos;
        }
    }

    private float Round(float x)
    {
        return Mathf.Round(x * PixelsPerUnit) / PixelsPerUnit;
    }
}

using UnityEngine;
using Unity.Cinemachine;

public class RPGCameraManager : MonoBehaviour
{
    public static RPGCameraManager sharedInstance = null;

    [Header("Cinemachine")]
    [SerializeField] private CinemachineCamera virtualCamera;
    [SerializeField] private string virtualCameraTag = "VirtualCamera";

    [Header("Startup")]
    [SerializeField] private bool findCameraOnStart = true;
    [SerializeField] private bool warnIfCameraMissing = true;

    public CinemachineCamera VirtualCamera => virtualCamera;

    private void Awake()
    {
        if (sharedInstance != null && sharedInstance != this)
        {
            Destroy(gameObject);
            return;
        }

        sharedInstance = this;

        if (findCameraOnStart)
        {
            EnsureVirtualCamera();
        }
    }

    private void Start()
    {
        if (findCameraOnStart)
        {
            EnsureVirtualCamera();
        }
    }

    public void SetFollowTarget(Transform target)
    {
        if (target == null)
        {
            Debug.LogWarning("RPGCameraManager cannot set Follow target because target is null.");
            return;
        }

        if (!EnsureVirtualCamera())
        {
            return;
        }

        virtualCamera.Follow = target;

        Debug.Log("Camera Follow target set to: " + target.name);
    }

    public void ClearFollowTarget()
    {
        if (!EnsureVirtualCamera())
        {
            return;
        }

        virtualCamera.Follow = null;

        Debug.Log("Camera Follow target cleared.");
    }

    private bool EnsureVirtualCamera()
    {
        if (virtualCamera != null)
        {
            return true;
        }

        virtualCamera = FindVirtualCamera();

        if (virtualCamera == null && warnIfCameraMissing)
        {
            Debug.LogWarning("RPGCameraManager could not find a CinemachineCamera. Assign CM vcam1 manually in the Inspector.");
        }

        return virtualCamera != null;
    }

    private CinemachineCamera FindVirtualCamera()
    {
        if (!string.IsNullOrEmpty(virtualCameraTag))
        {
            try
            {
                GameObject taggedCameraObject = GameObject.FindWithTag(virtualCameraTag);

                if (taggedCameraObject != null)
                {
                    CinemachineCamera taggedCamera = taggedCameraObject.GetComponent<CinemachineCamera>();

                    if (taggedCamera != null)
                    {
                        return taggedCamera;
                    }

                    if (warnIfCameraMissing)
                    {
                        Debug.LogWarning(
                            taggedCameraObject.name +
                            " is tagged as " +
                            virtualCameraTag +
                            " but does not have a CinemachineCamera component."
                        );
                    }
                }
            }
            catch (UnityException)
            {
                if (warnIfCameraMissing)
                {
                    Debug.LogWarning(
                        "The tag '" +
                        virtualCameraTag +
                        "' does not exist. Create it in Unity or assign the camera manually."
                    );
                }
            }
        }

        CinemachineCamera[] cameras = FindObjectsByType<CinemachineCamera>(FindObjectsSortMode.None);

        if (cameras.Length == 1)
        {
            return cameras[0];
        }

        if (cameras.Length > 1 && warnIfCameraMissing)
        {
            Debug.LogWarning(
                "More than one CinemachineCamera was found. Assign the correct one manually in the RPGCameraManager Inspector."
            );
        }
        return null;
    }
}

using System.Collections;
using UnityEngine;

public class RPGGameManager : MonoBehaviour
{
    public static RPGGameManager sharedInstance = null;

    [Header("Player")]
    [SerializeField] private Player player;
    [SerializeField] private SpawnPoint playerSpawnPoint;

    [Header("Respawn")]
    [SerializeField] private float respawnDelay = 1.5f;
    [SerializeField] private bool respawnPlayerOnDeath = true;

    [Header("Camera")]
    [SerializeField] private RPGCameraManager cameraManager;

    private Coroutine respawnCoroutine;

    public Player Player => player;
    public SpawnPoint PlayerSpawnPoint => playerSpawnPoint;

    private void Awake()
    {
        if (sharedInstance != null && sharedInstance != this)
        {
            Destroy(gameObject);
            return;
        }

        sharedInstance = this;
    }

    private void Start()
    {
        SetupScene();
    }

    public void SetupScene()
    {
        if (player == null)
        {
            GameObject playerObject = GameObject.FindWithTag("Player");

            if (playerObject != null)
            {
                player = playerObject.GetComponent<Player>();
            }
        }

        if (player == null)
        {
            Debug.LogWarning("RPGGameManager could not find a Player.");
            return;
        }

        if (playerSpawnPoint == null)
        {
            Debug.LogWarning("RPGGameManager has no PlayerSpawnPoint assigned.");
            return;
        }

        EnsureCameraManager();
        UpdateCameraFollowTarget();
    }

    public void NotifyPlayerDied()
    {
        if (!respawnPlayerOnDeath)
        {
            Debug.Log("Player died, but respawnPlayerOnDeath is disabled.");
            return;
        }

        if (respawnCoroutine != null)
        {
            StopCoroutine(respawnCoroutine);
        }

        respawnCoroutine = StartCoroutine(RespawnPlayerAfterDelay());
    }

    public void RespawnPlayerNow()
    {
        if (respawnCoroutine != null)
        {
            StopCoroutine(respawnCoroutine);
            respawnCoroutine = null;
        }

        RespawnPlayer();
    }

    public void SetPlayerSpawnPoint(SpawnPoint newSpawnPoint)
    {
        if (newSpawnPoint == null)
        {
            Debug.LogWarning("Tried to set player spawn point to null.");
            return;
        }

        playerSpawnPoint = newSpawnPoint;
    }

    private IEnumerator RespawnPlayerAfterDelay()
    {
        Debug.Log("Respawn timer started.");

        yield return new WaitForSeconds(respawnDelay);

        RespawnPlayer();

        respawnCoroutine = null;
    }

    private void RespawnPlayer()
    {
        if (player == null)
        {
            Debug.LogWarning("Cannot respawn player because Player reference is missing.");
            return;
        }

        if (playerSpawnPoint == null)
        {
            Debug.LogWarning("Cannot respawn player because PlayerSpawnPoint reference is missing.");
            return;
        }

        player.RespawnAt(playerSpawnPoint.transform);

        UpdateCameraFollowTarget();

        Debug.Log("Player respawned at spawn point.");
    }


    private bool EnsureCameraManager()
    {
        if (cameraManager != null)
        {
            return true;
        }

        cameraManager = RPGCameraManager.sharedInstance;

        if (cameraManager != null)
        {
            return true;
        }

        cameraManager = FindFirstObjectByType<RPGCameraManager>();

        if (cameraManager == null)
        {
            Debug.LogWarning("RPGGameManager could not find an RPGCameraManager. Camera follow will not be updated.");
            return false;
        }

        return true;
    }

    private void UpdateCameraFollowTarget()
    {
        if (player == null)
        {
            return;
        }

        if (!EnsureCameraManager())
        {
            return;
        }

        cameraManager.SetFollowTarget(player.transform);
    }
}

