[RequireComponent(typeof(Rigidbody2D))]
[RequireComponent(typeof(Animator))]
public class DuckFollower : MonoBehaviour
{
    [Header("References")]
    [SerializeField] private Transform player;

    [Header("Follow Settings")]
    [SerializeField] private float followBehindDistance = 0.75f;
    [SerializeField] private Vector2 extraOffset = Vector2.zero;
    [SerializeField] private float stopRadius = 0.12f;
    [SerializeField] private float maxSpeed = 3.5f;
    [SerializeField] private float followSmoothTime = 0.18f;
    [SerializeField] private float teleportIfFartherThan = 10f;

    [Header("Direction Detection")]
    [SerializeField] private float minimumPlayerMoveForDirection = 0.001f;

    [Header("Animation State Names")]
    [SerializeField] private string idleSouthState = "idleSouth";
    [SerializeField] private string walkSouthState = "walkSouth";
    [SerializeField] private string walkNorthState = "walkNorth";
    [SerializeField] private string walkEastState = "walkEast";
    [SerializeField] private string walkWestState = "walkWest";

    private Rigidbody2D rb;
    private Animator animator;

    private Vector2 lastPlayerPosition;
    private Vector2 lastFollowDirection = Vector2.down;
    private Vector2 smoothMoveVelocity;

    private string currentAnimState;

    private void Awake()
    {
        rb = GetComponent<Rigidbody2D>();
        animator = GetComponent<Animator>();

        rb.gravityScale = 0f;
        rb.freezeRotation = true;
        rb.interpolation = RigidbodyInterpolation2D.Interpolate;

        if (player != null)
        {
            lastPlayerPosition = player.position;
        }
    }

    private void Start()
    {
        if (player != null)
        {
            lastPlayerPosition = player.position;
        }
    }

    private void Reset()
    {
        followBehindDistance = 0.75f;
        extraOffset = Vector2.zero;
        stopRadius = 0.12f;
        maxSpeed = 3.5f;
        followSmoothTime = 0.18f;
        teleportIfFartherThan = 10f;
        minimumPlayerMoveForDirection = 0.001f;
    }

    private void FixedUpdate()
    {
        if (player == null)
        {
            smoothMoveVelocity = Vector2.zero;
            UpdateAnim(Vector2.zero);
            return;
        }

        Vector2 playerPosition = player.position;
        Vector2 playerDelta = playerPosition - lastPlayerPosition;

        if (playerDelta.sqrMagnitude > minimumPlayerMoveForDirection * minimumPlayerMoveForDirection)
        {
            lastFollowDirection = playerDelta.normalized;
        }

        lastPlayerPosition = playerPosition;

        Vector2 desiredPosition =
            playerPosition
            - lastFollowDirection * followBehindDistance
            + extraOffset;

        float distanceToDesiredPosition = Vector2.Distance(rb.position, desiredPosition);

        if (distanceToDesiredPosition > teleportIfFartherThan)
        {
            TeleportTo(desiredPosition);
            return;
        }

        if (distanceToDesiredPosition <= stopRadius)
        {
            smoothMoveVelocity = Vector2.zero;
            UpdateAnim(Vector2.zero);
            return;
        }

        Vector2 oldPosition = rb.position;

        Vector2 newPosition = Vector2.SmoothDamp(
            rb.position,
            desiredPosition,
            ref smoothMoveVelocity,
            followSmoothTime,
            maxSpeed,
            Time.fixedDeltaTime
        );

        rb.MovePosition(newPosition);

        Vector2 animationVelocity = (newPosition - oldPosition) / Time.fixedDeltaTime;
        UpdateAnim(animationVelocity);
    }

    private void TeleportTo(Vector2 targetPosition)
    {
        rb.position = targetPosition;
        smoothMoveVelocity = Vector2.zero;
        UpdateAnim(Vector2.zero);
    }

    private void UpdateAnim(Vector2 velocity)
    {
        if (animator == null)
        {
            return;
        }

        if (velocity.sqrMagnitude < 0.001f)
        {
            PlayAnim(idleSouthState);
            return;
        }

        if (Mathf.Abs(velocity.x) > Mathf.Abs(velocity.y))
        {
            if (velocity.x > 0f)
            {
                PlayAnim(walkEastState);
            }
            else
            {
                PlayAnim(walkWestState);
            }
        }
        else
        {
            if (velocity.y > 0f)
            {
                PlayAnim(walkNorthState);
            }
            else
            {
                PlayAnim(walkSouthState);
            }
        }
    }

    private void PlayAnim(string stateName)
    {
        if (string.IsNullOrEmpty(stateName))
        {
            return;
        }

        if (currentAnimState == stateName)
        {
            return;
        }

        currentAnimState = stateName;
        animator.Play(stateName);
    }
}

using UnityEngine;

[RequireComponent(typeof(SpriteRenderer))]
[RequireComponent(typeof(Animator))]
public class EnemyAnimationDriver : MonoBehaviour
{
    [Header("Movement Detection")]
    [SerializeField] private Rigidbody2D rb;
    [SerializeField] private float movingThreshold = 0.01f;

    [Header("Animator Parameters")]
    [SerializeField] private string isMovingParameter = "IsMoving";

    [Header("Sprite Facing")]
    [SerializeField] private bool flipSpriteWhenMovingLeft = true;

    private SpriteRenderer spriteRenderer;
    private Animator animator;

    private Vector2 lastPosition;

    private void Awake()
    {
        spriteRenderer = GetComponent<SpriteRenderer>();
        animator = GetComponent<Animator>();

        if (rb == null)
        {
            rb = GetComponent<Rigidbody2D>();
        }

        lastPosition = transform.position;
    }

    private void Update()
    {
        Vector2 velocity = GetMovementVelocity();

        bool isMoving = velocity.sqrMagnitude > movingThreshold * movingThreshold;

        animator.SetBool(isMovingParameter, isMoving);

        if (flipSpriteWhenMovingLeft && Mathf.Abs(velocity.x) > movingThreshold)
        {
            spriteRenderer.flipX = velocity.x < 0f;
        }

        lastPosition = transform.position;
    }

    private Vector2 GetMovementVelocity()
    {
        if (rb != null)
        {
            return rb.linearVelocity;
        }

        Vector2 currentPosition = transform.position;
        Vector2 estimatedVelocity = (currentPosition - lastPosition) / Mathf.Max(Time.deltaTime, 0.0001f);
        return estimatedVelocity;
    }
}

using UnityEngine;

public class EnemyHitPoints : MonoBehaviour
{
    [Header("Health")]
    [SerializeField] private int maxHitPoints = 3;
    [SerializeField] private int startingHitPoints = 3;

    [Header("Death")]
    [SerializeField] private bool destroyOnDeath = true;
    [SerializeField] private float destroyDelay = 0f;
    [SerializeField] private bool disableInsteadOfDestroy = false;

    private int currentHitPoints;
    private bool isDead;

    public int CurrentHitPoints => currentHitPoints;
    public int MaxHitPoints => maxHitPoints;
    public bool IsDead => isDead;

    private void Awake()
    {
        maxHitPoints = Mathf.Max(1, maxHitPoints);
        startingHitPoints = Mathf.Clamp(startingHitPoints, 1, maxHitPoints);
        currentHitPoints = startingHitPoints;
    }

    public void TakeDamage(int damageAmount)
    {
        if (isDead)
        {
            return;
        }

        if (damageAmount <= 0)
        {
            return;
        }

        currentHitPoints -= damageAmount;
        currentHitPoints = Mathf.Clamp(currentHitPoints, 0, maxHitPoints);

        Debug.Log($"{gameObject.name} took {damageAmount} damage. HP: {currentHitPoints}/{maxHitPoints}");

        if (currentHitPoints <= 0)
        {
            Die();
        }
    }

    public void Heal(int healAmount)
    {
        if (isDead)
        {
            return;
        }

        if (healAmount <= 0)
        {
            return;
        }

        currentHitPoints += healAmount;
        currentHitPoints = Mathf.Clamp(currentHitPoints, 0, maxHitPoints);

        Debug.Log($"{gameObject.name} healed by {healAmount}. HP: {currentHitPoints}/{maxHitPoints}");
    }

    public void ResetHitPoints()
    {
        isDead = false;
        currentHitPoints = startingHitPoints;
        gameObject.SetActive(true);
    }

    private void Die()
    {
        if (isDead)
        {
            return;
        }

        isDead = true;

        Debug.Log($"{gameObject.name} died.");

        Collider2D enemyCollider = GetComponent<Collider2D>();
        if (enemyCollider != null)
        {
            enemyCollider.enabled = false;
        }

        Rigidbody2D rb = GetComponent<Rigidbody2D>();
        if (rb != null)
        {
            rb.linearVelocity = Vector2.zero;
            rb.simulated = false;
        }

        Animator animator = GetComponent<Animator>();
        if (animator != null)
        {
            animator.SetBool("IsMoving", false);
        }

        if (disableInsteadOfDestroy)
        {
            gameObject.SetActive(false);
            return;
        }

        if (destroyOnDeath)
        {
            Destroy(gameObject, destroyDelay);
        }
    }
}

using UnityEngine;
using UnityEngine.UI;

public class HealthBar : MonoBehaviour
{
    public HitPoints hitPoints;

    [HideInInspector]
    public Character character;
    public Image meterImage;
    public Text hpText;
    float maxHitPoints;

    // Start is called once before the first execution of Update after the MonoBehaviour is created
    void Start()
    {
        maxHitPoints = character.maxHitPoints;
    }

    // Update is called once per frame
    void Update()
    {
        if (character != null)
        {
            meterImage.fillAmount = hitPoints.value / maxHitPoints;
            hpText.text = "HP:" + (meterImage.fillAmount * 100);
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class MovementController : MonoBehaviour
{
    public float movementSpeed = 3.0f;

    public Vector2 MoveDir { get; private set; }
    public Vector2 LastMoveDir { get; private set; } = Vector2.down;

    private Animator animator;
    Rigidbody2D rb2D;

    private const string animationState = "AnimationState";

    private enum CharStates
    {
        walkEast = 1,
        walkSouth = 2,
        walkWest = 3,
        walkNorth = 4,

        idleSouth = 5
    }

    private void Start()
    {
        animator = GetComponent<Animator>();
        rb2D = GetComponent<Rigidbody2D>();
    }

    private void Update()
    {
        ReadInput();
        UpdateState();
    }

    void FixedUpdate()
    {
        MoveCharacter();
    }

    private void ReadInput()
    {
        float x = Input.GetAxisRaw("Horizontal");
        float y = Input.GetAxisRaw("Vertical");

        Vector2 v = new Vector2(x, y);

        if (v.sqrMagnitude > 0.0001f)
        {
            v.Normalize();
            MoveDir = v;
            LastMoveDir = v;
        }
        else
        {
            MoveDir = Vector2.zero;
        }
    }

    private void MoveCharacter()
    {
        rb2D.linearVelocity = MoveDir * movementSpeed;
    }

    private void UpdateState()
    {
        if (MoveDir.x > 0) animator.SetInteger(animationState, (int)CharStates.walkEast);
        else if (MoveDir.x < 0) animator.SetInteger(animationState, (int)CharStates.walkWest);
        else if (MoveDir.y > 0) animator.SetInteger(animationState, (int)CharStates.walkNorth);
        else if (MoveDir.y < 0) animator.SetInteger(animationState, (int)CharStates.walkSouth);
        else animator.SetInteger(animationState, (int)CharStates.idleSouth);
    }

}

using UnityEngine;

public class Player : Character
{
    [Header("Inventory")]
    public Inventory inventoryPrefab;
    private Inventory inventory;

    [Header("Health Bar")]
    public HealthBar healthBarPrefab;
    private HealthBar healthBar;

    [Header("Enemy Contact Damage")]
    [SerializeField] private int enemyTouchDamage = 1;
    [SerializeField] private float enemyDamageCooldown = 1f;

    private float nextEnemyDamageTime;
    private bool isDead;

    public bool IsDead => isDead;

    public void Start()
    {
        hitPoints.value = startingHitPoints;

        inventory = Instantiate(inventoryPrefab);

        healthBar = Instantiate(healthBarPrefab);
        healthBar.character = this;

        isDead = false;
    }

    private void OnTriggerEnter2D(Collider2D collision)
    {
        print("Trigger hit: " + collision.gameObject.name);

        if (collision.gameObject.CompareTag("Enemy"))
        {
            TryTakeEnemyContactDamage();
            return;
        }

        if (collision.gameObject.CompareTag("CanBePickedUp"))
        {
            HandlePickup(collision);
        }
    }

    private void OnTriggerStay2D(Collider2D collision)
    {
        if (collision.gameObject.CompareTag("Enemy"))
        {
            TryTakeEnemyContactDamage();
        }
    }

    private void HandlePickup(Collider2D collision)
    {
        print("Tag matched");

        Consumable consumable = collision.gameObject.GetComponent<Consumable>();

        if (consumable == null)
        {
            return;
        }

        Item hitObject = consumable.item;

        if (hitObject == null)
        {
            return;
        }

        print("Item type: " + hitObject.itemType + ", stackable: " + hitObject.stackable);

        bool shouldDisappear = false;

        switch (hitObject.itemType)
        {
            case Item.ItemType.COIN:
                shouldDisappear = inventory.AddItem(hitObject);
                print("AddItem returned: " + shouldDisappear);
                break;

            case Item.ItemType.HEALTH:
                shouldDisappear = Heal(hitObject.quantity);
                break;

            default:
                break;
        }

        if (shouldDisappear)
        {
            collision.gameObject.SetActive(false);
        }
    }

    private void TryTakeEnemyContactDamage()
    {
        if (isDead)
        {
            return;
        }

        if (Time.time < nextEnemyDamageTime)
        {
            return;
        }

        TakeDamage(enemyTouchDamage);
        nextEnemyDamageTime = Time.time + enemyDamageCooldown;
    }

    public bool AdjustHitPoints(int amount)
    {
        if (amount > 0)
        {
            return Heal(amount);
        }

        if (amount < 0)
        {
            TakeDamage(-amount);
            return true;
        }

        return false;
    }

    public bool Heal(int amount)
    {
        if (isDead)
        {
            return false;
        }

        if (amount <= 0)
        {
            return false;
        }

        if (hitPoints.value >= maxHitPoints)
        {
            return false;
        }

        hitPoints.value = Mathf.Clamp(hitPoints.value + amount, 0f, maxHitPoints);

        print("Healed by: " + amount + ". New HP: " + hitPoints.value);

        return true;
    }

    public void TakeDamage(int amount)
    {
        if (isDead)
        {
            return;
        }

        if (amount <= 0)
        {
            return;
        }

        hitPoints.value = Mathf.Clamp(hitPoints.value - amount, 0f, maxHitPoints);

        print("Player took damage: " + amount + ". New HP: " + hitPoints.value);

        if (hitPoints.value <= 0f)
        {
            KillCharacter();
        }
    }

    public void RespawnAt(Transform spawnPoint)
    {
        if (spawnPoint == null)
        {
            Debug.LogWarning("Cannot respawn player because spawnPoint is null.");
            return;
        }

        gameObject.SetActive(true);

        transform.position = spawnPoint.position;
        transform.rotation = spawnPoint.rotation;

        Rigidbody2D rb = GetComponent<Rigidbody2D>();

        if (rb != null)
        {
            rb.linearVelocity = Vector2.zero;
            rb.angularVelocity = 0f;
        }

        hitPoints.value = startingHitPoints;
        nextEnemyDamageTime = Time.time + 0.25f;
        isDead = false;

        print("Player respawned. HP restored to: " + hitPoints.value);
    }

    private void Die()
    {
        if (isDead)
        {
            return;
        }

        isDead = true;

        print("Player died.");

        if (RPGGameManager.sharedInstance != null)
        {
            RPGGameManager.sharedInstance.NotifyPlayerDied();
        }
        else
        {
            Debug.LogWarning("Player died, but no RPGGameManager.sharedInstance was found.");
        }

        gameObject.SetActive(false);
    }
}

